/* No backend exists in this independent preview. Only non-sensitive preferences
   are persisted; password, 2FA and real session changes require an auth service. */
const KEY='settings-preview-v3',base={profile:{name:'Oyeleye Ogunsanya',email:'Leye@company.com'},theme:'light',collapsed:false,notifications:[{id:1,text:'Your monthly report is ready to review.',time:'Just now',unread:true},{id:2,text:'A sign-in was detected from Lagos, Nigeria.',time:'2 hours ago',unread:true}]};
const stored=(()=>{try{return JSON.parse(localStorage.getItem(KEY))||{}}catch{return{}}})();
const state={...base,...stored,profile:{...base.profile,...stored.profile},tab:new URLSearchParams(location.search).get('tab')||'general',sessions:null};
const shell=document.querySelector('#app-shell'),nav=document.querySelector('#navigation'),content=document.querySelector('#tab-content'),overlay=document.querySelector('#overlay-root');let lastTrigger;
const paths={home:'M3 10.8 12 3l9 7.8v9.2h-6v-6H9v6H3z',users:'M16 20v-1.8c0-2-1.8-3.7-4-3.7s-4 1.7-4 3.7V20M12 11a3.3 3.3 0 1 0 0-6.6 3.3 3.3 0 0 0 0 6.6M19 8v4M21 10h-4',orders:'M7 4v16M17 4v16M3 8h8M13 16h8M13 8h8M3 16h8',receipt:'M6 3h12v18l-3-2-3 2-3-2-3 2-3 2zM9 8h6M9 12h6',code:'M8 8 4 12l4 4M16 8l4 4-4 4M14 5l-4 14',report:'M6 4h12v16H6zM9 8h6M9 12h6M9 16h3',building:'M4 21h16M6 18V7h8v11M14 10h4v8M9 10h2M9 14h2',plus:'M12 5v14M5 12h14',audit:'M4 5h5v5H4zM15 14h5v5h-5zM9 7h6M9 17h6M7 10v4M17 10v4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4.9 15 3.7 16.2l2.1 3.6 1.7-.5a7 7 0 0 0 1.9 1.1l.4 1.7h4.2l.4-1.7a7 7 0 0 0 1.9-1.1l1.7.5 2.1-3.6-1.2-1.2c.1-.6.1-1.3 0-1.9l1.2-1.2-2.1-3.6-1.7.5a7 7 0 0 0-1.9-1.1L14.2 3H10l-.4 1.7a7 7 0 0 0-1.9 1.1L6 5.3 3.9 8.9l1.2 1.2a7 7 0 0 0-.2 1.9L3.7 13.2z',question:'M9.5 9a2.7 2.7 0 1 1 4.5 2c-1 .8-2 1.3-2 2.8M12 18h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z',menu:'M4 7h16M4 12h16M4 17h16',search:'m20 20-4.2-4.2M10.7 18a7.3 7.3 0 1 1 0-14.6 7.3 7.3 0 0 1 0 14.6z',sun:'M12 3v2M12 19v2M5.6 5.6 7 7M17 17l1.4 1.4M3 12h2M19 12h2M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8Z',bell:'M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',sliders:'M5 5v14M12 5v14M19 5v14M2 9h6M9 15h6M16 10h6',devices:'M4 5h12v10H4zM8 19h4M10 15v4M18 9h2v10h-7',sessionDesktop:'M4 5h16v11H4zM9 20h6M12 16v4',sessionWindow:'M5 5h14v14H5zM8 15h8',sessionLaptop:'M5 5h14v11H5zM2 19h20',headset:'M4 13v-1a8 8 0 0 1 16 0v1M4 13h3v5H5a1 1 0 0 1-1-1zM20 13h-3v5h2a1 1 0 0 0 1-1zM17 18c0 2-2 3-5 3',edit:'m14.5 5.5 4 4M4 20l4.3-1 10-10a2.8 2.8 0 0 0-4-4l-10 10z',shield:'M12 3 20 6v5c0 5-3.4 8.4-8 10-4.6-1.6-8-5-8-10V6zM9 12l2 2 4-4',lock:'M6 10h12v10H6zM8 10V7a4 4 0 0 1 8 0v3',arrow:'m9 18 6-6-6-6',close:'M6 6l12 12M18 6 6 18',check:'m5 12 4 4L19 6',external:'M14 5h5v5M19 5l-8 8',bank:'M3 9h18M5 9v9m4-9v9m6-9v9m4-9v9M3 18h18M12 3 3 7h18L12 3z',warning:'M12 4 2.5 20h19L12 4zM12 10v4M12 16.5h.01'};
function icon(n){return `<svg class="svg-icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.settings}"></path></svg>`}function icons(root=document){root.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon))}function esc(v){return String(v).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}function persist(){localStorage.setItem(KEY,JSON.stringify({profile:state.profile,theme:state.theme,collapsed:state.collapsed,notifications:state.notifications}))}
function navMarkup(){const make=x=>x.map(([r,i,l])=>`<button class="nav-item" data-route="${r}" data-label="${l}" ${r==='/settings'?'aria-current="page"':''}>${icon(i)}<span class="nav-copy">${l}</span></button>`).join(''),primary=[['/dashboard','home','Home'],['/account','bank','Account'],['/users','users','Users'],['/orders','orders','Orders'],['/transactions','receipt','Transactions'],['/api','code','API'],['/reports','report','Report']],trade=[['/business-trading','building','Business trading'],['/accounts/new','plus','New account']],more=[['/audit-log','audit','Audit log'],['/settings','settings','Settings']];nav.innerHTML=make(primary)+`<span class="nav-section">Trading Account</span>`+make(trade)+`<span class="nav-section">More</span>`+make(more)}
function render(){shell.classList.toggle('is-collapsed',state.collapsed);const collapse=document.querySelector('.collapse');collapse.innerHTML=icon(state.collapsed?'menu':'arrow');collapse.dataset.tooltip=state.collapsed?'Expand sidebar':'Collapse sidebar';document.querySelectorAll('[role=tab]').forEach(t=>t.setAttribute('aria-selected',t.dataset.tab===state.tab));document.querySelector('.notification-dot').hidden=!state.notifications.some(n=>n.unread);renderPanel()}
function renderPanel(){content.innerHTML=({general:general,sessions,support})[state.tab]();icons(content);if(state.tab==='sessions')loadSessions()}
function general(){let t=state.theme;return `<div role="tabpanel" id="general-panel"><section class="settings-section"><div class="section-heading"><h2>Personal information</h2><p>See and edit your personal information.</p></div><div><div class="profile-avatar">${esc(state.profile.name[0])}</div><div class="field-row"><div><span class="field-label">Full name</span><strong class="field-value">${esc(state.profile.name)}</strong></div><button class="field-action" data-action="edit-name" aria-label="Edit full name">${icon('edit')}</button></div><div class="field-row"><div><span class="field-label">Email address</span><strong class="field-value">${esc(state.profile.email)}</strong></div><button class="field-action" data-action="edit-email" aria-label="Change email address">${icon('edit')}</button></div></div></section><section class="settings-section"><div class="section-heading"><h2>Appearance</h2><p>Set your appearance and preferences.</p></div><div class="theme-options">${['light','system','dark'].map(x=>`<button class="theme-option ${t===x?'selected':''}" data-action="theme" data-theme="${x}" aria-pressed="${t===x}"><span class="theme-preview ${x==='light'?'':x}"></span><span class="theme-label"><i class="radio-mark"></i>${x[0].toUpperCase()+x.slice(1)} mode</span></button>`).join('')}</div></section><section class="settings-section"><div class="section-heading"><h2>Security</h2><p>Update password and set 2FA</p></div><div><div class="field-row"><div><span class="field-label">Role</span><strong class="field-value"><u>Learn about your role</u></strong></div><button class="role-badge" data-action="role">${icon('shield')} Operations</button></div><div class="field-row"><div><span class="field-label">Password</span><strong class="field-value">••••••••</strong></div><button class="field-action" data-action="password" aria-label="Change password">${icon('edit')}</button></div><div class="field-row"><div><span class="field-label">Authentication</span><strong class="field-value">No 2FA set</strong></div><button class="text-action" data-action="two-factor">Set 2FA ${icon('arrow')}</button></div><p class="notice">Security changes need an authenticated server connection. This static preview does not claim to change passwords, 2FA, or sessions.</p></div></section></div>`}
function sessionTable(){
  const heading='<div class="session-table-head" role="row"><span role="columnheader">Location and IP</span><span role="columnheader">OS &amp; Browser</span><span role="columnheader">Last active</span><span role="columnheader">Manage</span></div>';
  if(!state.sessions)return `<div class="session-table is-loading" role="table" aria-label="Active sessions" aria-busy="true">${heading}<div class="session-skeleton" role="rowgroup">${Array.from({length:4},()=>'<div class="session-skeleton-row"><span></span><span></span><span></span><span></span></div>').join('')}</div></div>`;
  const rows=state.sessions.map(s=>`<div class="session-row" role="row" data-session-id="${s.id}"><div class="session-location" role="cell" data-label="Location and IP"><span class="session-device">${icon(s.device)}</span><span><strong>${esc(s.location)}</strong><small>${esc(s.ip)}</small></span></div><div class="session-os" role="cell" data-label="OS & Browser"><strong>${esc(s.os)}</strong><small>${esc(s.browser)}</small></div><div class="session-active" role="cell" data-label="Last active">${esc(s.active)}</div><div class="session-manage" role="cell" data-label="Manage">${s.current?'<span class="current-session">Current session</span>':`<button class="session-signout" type="button" data-action="revoke-session" data-session-id="${s.id}">Sign out</button>`}</div></div>`).join('');
  return `<div class="session-table" role="table" aria-label="Active sessions" aria-busy="false">${heading}<div role="rowgroup">${rows}</div></div>`;
}
function sessions(){const otherCount=state.sessions?.filter(s=>!s.current).length;return `<div role="tabpanel" id="sessions-panel"><section class="sessions-page"><div class="sessions-intro"><h2>Sessions</h2><p>All your active sessions are listed below, end any session you do not trust or recognise</p><button class="button secondary session-signout-all" type="button" data-action="sign-out-others" ${state.sessions===null||otherCount===0?'disabled':''}>Sign out of other sessions</button></div><div data-sessions>${sessionTable()}</div></section></div>`}function support(){return `<div role="tabpanel" id="support-panel"><div class="support-grid"><article class="support-card">${icon('question')}<h2>Help centre</h2><p>Read guides and answers to common questions.</p><button data-action="help-centre">Open help centre ${icon('external')}</button></article><article class="support-card">${icon('headset')}<h2>Contact support</h2><p>Send a message to the support team.</p><button data-action="support">Contact support ${icon('arrow')}</button></article><article class="support-card">${icon('report')}<h2>Report a problem</h2><p>Tell us about a technical issue with the product.</p><button data-action="report-problem">Report a problem ${icon('arrow')}</button></article></div></div>`}
function setTab(tab){state.tab=tab;let u=new URL(location);u.searchParams.set('tab',tab);history.pushState({},'',u);render()}function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;persist();render()}function syncThemeToggle(){const button=document.querySelector('[data-action="toggle-theme"]');if(!button)return;const dark=document.documentElement.dataset.theme==='dark',label=dark?'Switch to light mode':'Switch to dark mode';button.innerHTML=icon(dark?'moon':'sun');button.setAttribute('aria-label',label);button.setAttribute('aria-pressed',String(dark));button.dataset.tooltip=label}function toggleHeaderTheme(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}
function loadSessions(){if(state.sessions)return;setTimeout(()=>{if(state.tab!=='sessions')return;state.sessions=[{id:'current',location:'Manchester, United Kingdom',ip:'817.178.200.30',os:'Windows 11',browser:'Chrome',active:'Just now',device:'sessionDesktop',current:true},{id:'manchester',location:'Manchester, United Kingdom',ip:'817.178.200.30',os:'Windows 11',browser:'Chrome',active:'8 hours ago',device:'sessionWindow',current:false},{id:'london',location:'London, United Kingdom',ip:'817.178.200.30',os:'macOS 15',browser:'Safari',active:'1 month ago',device:'sessionLaptop',current:false},{id:'lagos',location:'Lagos, Nigeria',ip:'817.178.200.30',os:'Windows 10',browser:'Firefox',active:'4 months ago',device:'sessionLaptop',current:false}];renderPanel()},420)}
function toast(message,type='success',options={}){return window.productToast?.push({message,type,...options})}
function sessionSignoutModal(sessionId){
  const all=sessionId==='all',session=state.sessions?.find(s=>s.id===sessionId&&!s.current),count=state.sessions?.filter(s=>!s.current).length||0;
  if((all&&!count)||(!all&&!session))return toast('There are no other active sessions to sign out.','info',{title:'Sessions are up to date'});
  const title=all?'Sign out of other sessions?':'Sign out this session?';
  const description=all?'Every session except this current one will be removed.':'This device will need to sign in again before it can access the account.';
  const summary=all?`${count} other active session${count===1?'':'s'}`:`${session.location} · ${session.os} · ${session.browser}`;
  modal(title,description,`<div class="session-confirm-summary">${icon(all?'devices':session.device)}<div><strong>${esc(summary)}</strong><span>This preview updates the local session list. A connected authentication service is required to revoke a real session.</span></div></div>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button danger" data-action="confirm-session-signout" data-session-id="${all?'all':session.id}">Sign out</button>`);
}
function confirmSessionSignout(button){
  const sessionId=button.dataset.sessionId,all=sessionId==='all',session=state.sessions?.find(s=>s.id===sessionId);
  if(!all&&!session)return closeOverlay();
  button.disabled=true;button.innerHTML='<i class="spinner"></i>Signing out…';
  const notice=toast(all?'Signing out of your other sessions.':`Signing out the ${session.location} session.`,'loading',{title:'Updating sessions',duration:0,progress:35});
  setTimeout(()=>{
    state.sessions=all?state.sessions.filter(s=>s.current):state.sessions.filter(s=>s.id!==sessionId);
    closeOverlay();
    setTimeout(()=>{if(state.tab==='sessions')renderPanel();window.productToast?.update(notice,{type:'success',title:all?'Other sessions signed out':'Session signed out',message:all?'Only your current session remains.':`${session.location} was removed from this preview.`,duration:4500,progress:100})},170);
  },560);
}
function closeOverlay(){if(!overlay.innerHTML)return;overlay.innerHTML='';overlay.setAttribute('aria-hidden','true');lastTrigger?.focus();lastTrigger=null}function modal(title,description,body,footer){overlay.innerHTML=`<div class="backdrop" data-backdrop><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><div><h2 id="dialog-title">${title}</h2><p>${description}</p></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}</section></div>`;overlay.removeAttribute('aria-hidden');overlay.querySelector('input,button,select,textarea')?.focus()}
function simpleModal(kind){if(kind==='edit-name')modal('Edit full name','This update is saved to the local preview preference store.',`<form id="name-form"><div class="form-field"><label for="full-name">Full name</label><input id="full-name" value="${esc(state.profile.name)}" autocomplete="name"><small class="error-message"></small></div></form>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button" form="name-form">Save name</button>`);if(kind==='edit-email')modal('Change email address','A secure backend is needed to send and verify an email-change link.',`<form id="email-form"><div class="form-field"><label for="email">New email address</label><input id="email" type="email" value="${esc(state.profile.email)}"><small class="error-message"></small></div><p class="notice">No verification email is sent from this standalone preview, and the current email remains unchanged.</p></form>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button" form="email-form">Request verification</button>`);if(kind==='password')modal('Change password','This requires reauthentication and a secure server-side password flow.',`<form id="password-form"><div class="form-field"><label for="current-password">Current password</label><input id="current-password" type="password" autocomplete="current-password"></div><div class="form-field"><label for="new-password">New password</label><input id="new-password" type="password" autocomplete="new-password"><small class="form-help">Use at least 12 characters with a mix of character types.</small></div><div class="form-field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" type="password" autocomplete="new-password"><small class="error-message"></small></div></form>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button" form="password-form">Continue securely</button>`);if(kind==='role')modal('Your role','Roles define which areas of the workspace you can access.',`<p class="notice"><strong>Operations</strong><br>You can manage users, orders, transactions, reports, and account settings. Contact an administrator to change your role.</p>`,`<button class="button" data-action="close">Done</button>`);if(kind==='two-factor')modal('Two-factor authentication','Set up requires a server-generated secret and verification code.',`<p class="notice">2FA stays disabled in this standalone preview. A real service must generate a TOTP secret, verify the first code, and store recovery codes securely before this status can change.</p>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button" data-action="backend-required">Connect secure backend</button>`)}
function supportModal(report){modal(report?'Report a problem':'Contact support',report?'Describe the problem without including passwords or private credentials.':'We will create a reference for this mock support request.',`<form id="support-form"><div class="form-field"><label for="subject">${report?'Issue title':'Subject'}</label><input id="subject" required maxlength="120"><small class="error-message"></small></div>${report?'':`<div class="form-field"><label for="category">Category</label><select id="category" required><option value="">Select a category</option><option>Account</option><option>Billing</option><option>Technical support</option></select></div>`}<div class="form-field"><label for="message">${report?'What happened':'Message'}</label><textarea id="message" required minlength="20"></textarea><small class="form-help">At least 20 characters. Attachments are unavailable in this static preview.</small></div></form>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button" form="support-form">Submit request</button>`)}
function closePopovers(){document.querySelectorAll('.popover').forEach(x=>x.remove())}function showNotes(){closePopovers();let p=document.createElement('div');p.className='popover notification-popover';p.innerHTML=`<div class="popover-title">Notifications <button data-action="mark-all">Mark all read</button></div>${state.notifications.length?state.notifications.map(n=>`<div class="notification-item ${n.unread?'unread':''}" data-action="read-note" data-id="${n.id}">${icon('bell')}<div><p>${n.text}</p><time>${n.time}</time></div></div>`).join(''):'<div class="search-empty">You’re all caught up.</div>'}`;document.body.append(p)}
function openMobile(){if(document.querySelector('.mobile-nav'))return;let d=document.createElement('aside');d.className='mobile-nav open';d.setAttribute('aria-label','Mobile navigation');let liveNav=document.querySelector('.sidebar .navigation');d.innerHTML=`<div class="sidebar-top"><button class="brand" data-action="business"><span class="brand-mark">W</span><span>Business name</span></button><button class="icon-button" data-action="close-mobile" aria-label="Close navigation">${icon('close')}</button></div><nav class="navigation">${liveNav?liveNav.innerHTML:nav.innerHTML}</nav><button class="nav-item help" data-sidebar-route="/help">${icon('question')}<span>Help</span></button>`;document.body.append(d);let bg=document.createElement('div');bg.className='mobile-nav-backdrop';bg.dataset.action='close-mobile';document.body.append(bg)}function closeMobile(){document.querySelector('.mobile-nav')?.remove();document.querySelector('.mobile-nav-backdrop')?.remove()}
function action(target){let a=target.closest('[data-action]');if(!a)return;lastTrigger=a;let k=a.dataset.action;if(k==='close')return closeOverlay();if(k==='collapse'){state.collapsed=!state.collapsed;persist();return render()}if(k==='mobile-menu')return openMobile();if(k==='close-mobile')return closeMobile();if(k==='toggle-theme'){closePopovers();return toggleHeaderTheme()}if(k==='notifications')return showNotes();if(k==='theme'){setTheme(a.dataset.theme);closePopovers();return toast('Theme updated')}if(['edit-name','edit-email','password','role','two-factor'].includes(k))return simpleModal(k);if(k==='support')return supportModal(false);if(k==='report-problem')return supportModal(true);if(k==='help-centre'||k==='business')return toast('This route opens in the host application.');if(k==='backend-required')return toast('Connect an authenticated backend to continue.','error');if(k==='sign-out-others')return sessionSignoutModal('all');if(k==='revoke-session')return sessionSignoutModal(a.dataset.sessionId);if(k==='confirm-session-signout')return confirmSessionSignout(a);if(k==='mark-all'){state.notifications=state.notifications.map(x=>({...x,unread:false}));persist();render();return showNotes()}if(k==='read-note'){state.notifications=state.notifications.map(x=>x.id===Number(a.dataset.id)?{...x,unread:false}:x);persist();render();return showNotes()}}
document.addEventListener('click',e=>{let tab=e.target.closest('[data-tab]');if(tab)return setTab(tab.dataset.tab);let route=e.target.closest('[data-route]');if(route){closeMobile();return route.dataset.route==='/settings'?setTab('general'):toast(`${route.dataset.label||'This page'} opens in the host application.`)}if(e.target.closest('[data-backdrop]')===e.target)return closeOverlay();if(!e.target.closest('.popover')&&!e.target.closest('[data-action="notifications"]'))closePopovers();action(e.target)});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target;if(f.id==='name-form'){let i=f.querySelector('input'),v=i.value.trim(),err=f.querySelector('.error-message');if(v.length<2){err.textContent='Enter at least two characters.';i.focus();return}state.profile.name=v;persist();closeOverlay();render();return toast('Name updated')}if(f.id==='email-form'){let i=f.querySelector('input'),err=f.querySelector('.error-message');if(!i.checkValidity()){err.textContent='Enter a valid email address.';i.focus();return}return toast('A secure backend is required to send verification.','error')}if(f.id==='password-form'){let cur=f.querySelector('#current-password'),n=f.querySelector('#new-password'),c=f.querySelector('#confirm-password'),err=f.querySelector('.error-message');if(!cur.value||n.value.length<12||n.value!==c.value){err.textContent=n.value!==c.value?'Passwords do not match.':'Enter your current password and a new password of at least 12 characters.';c.focus();return}f.reset();return toast('A secure server is required to change passwords.','error')}if(f.id==='support-form'){let s=f.querySelector('#subject'),c=f.querySelector('#category'),m=f.querySelector('#message');if(!s.value.trim()||(c&&!c.value)||m.value.trim().length<20)return toast('Complete the required fields before submitting.','error');let b=document.querySelector('[form="support-form"]');b.disabled=true;b.innerHTML='<i class="spinner"></i>Submitting…';return setTimeout(()=>{closeOverlay();toast(`Request submitted · #SUP-${Math.floor(10000+Math.random()*89999)}`)},550)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePopovers();closeMobile();closeOverlay()}if(e.key==='Tab'&&overlay.innerHTML){let f=[...overlay.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function navMarkupRef(){const make=x=>x.map(([r,i,l])=>`<button class="nav-item" data-route="${r}" data-label="${l}" ${r==='/settings'?'aria-current="page"':''}>${icon(i)}<span class="nav-copy">${l}</span></button>`).join(''),primary=[['/dashboard','home','Home'],['/account','bank','Account'],['/users','users','Users'],['/orders','orders','Orders'],['/transactions','receipt','Transactions'],['/api','code','API'],['/reports','report','Report']],trade=[['/business-trading','building','Business trading'],['/accounts/new','plus','New account']],more=[['/audit-log','audit','Audit log'],['/settings','home','Settings']];nav.innerHTML=make(primary)+`<span class="nav-section">Trading Account</span>`+make(trade)+`<span class="nav-section">More</span>`+make(more)}
function renderRef(){shell.classList.toggle('is-collapsed',state.collapsed);const collapse=document.querySelector('.collapse');collapse.innerHTML=icon(state.collapsed?'menu':'panel');collapse.dataset.tooltip=state.collapsed?'Expand sidebar':'Collapse sidebar';document.querySelectorAll('[role=tab]').forEach(t=>t.setAttribute('aria-selected',t.dataset.tab===state.tab));document.querySelector('.notification-dot').hidden=!state.notifications.some(n=>n.unread);syncThemeToggle();renderPanel()}
function generalRef(){let t=state.theme,avatar=state.profile.avatar?`<img src="${state.profile.avatar}" alt="">`:'L';return `<div role="tabpanel" id="general-panel"><section class="settings-section"><div class="section-heading"><h2>Personal information</h2><p>See and edit your personal information.</p></div><div><div class="avatar-wrap"><div class="profile-avatar">${avatar}</div><button class="avatar-edit" data-action="edit-avatar" aria-label="Update profile photo">${icon('edit')}</button></div><div class="field-row"><div><span class="field-label">Full name</span><strong class="field-value">${esc(state.profile.name)}</strong></div><button class="field-action" data-action="edit-name" aria-label="Edit full name">${icon('edit')}</button></div><div class="field-row"><div><span class="field-label">Email address</span><strong class="field-value">${esc(state.profile.email)}</strong></div><button class="field-action" data-action="edit-email" aria-label="Change email address">${icon('edit')}</button></div></div></section><section class="settings-section"><div class="section-heading"><h2>Appearance</h2><p>Set your appearance and preferences.</p></div><div class="theme-options">${['light','system','dark'].map(x=>`<button class="theme-option ${t===x?'selected':''}" data-action="theme" data-theme="${x}" aria-pressed="${t===x}"><span class="theme-preview ${x==='light'?'':x}"></span><span class="theme-label"><i class="radio-mark"></i>${x[0].toUpperCase()+x.slice(1)} mode</span></button>`).join('')}</div></section><section class="settings-section"><div class="section-heading"><h2>Security</h2><p>Update password and set 2FA</p></div><div><div class="field-row"><div><span class="field-label">Role</span><strong class="field-value"><u>Learn about your role</u></strong></div><button class="role-badge" data-action="role">${icon('shield')} Operations</button></div><div class="field-row"><div><span class="field-label">Password</span><strong class="field-value">••••••••</strong></div><button class="field-action" data-action="password" aria-label="Change password">${icon('edit')}</button></div><div class="field-row"><div><span class="field-label">Authentication</span><strong class="field-value">No 2FA set</strong></div><button class="text-action" data-action="two-factor">Set 2FA ${icon('arrow')}</button></div></div></section></div>`}
function avatarModal(){modal('Update profile photo','Choose a square JPG, PNG or WebP image under 2 MB.',`<form id="avatar-form"><div class="form-field"><label for="avatar-file">Profile photo</label><input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp" required><small class="error-message"></small></div></form>`,`<button class="button secondary" data-action="close">Cancel</button><button class="button" form="avatar-form">Save photo</button>`)}
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-action="edit-avatar"]');if(trigger){lastTrigger=trigger;avatarModal()}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='avatar-form')return;e.preventDefault();const input=e.target.querySelector('input'),error=e.target.querySelector('.error-message'),file=input.files[0];if(!file){error.textContent='Choose an image.';return}if(file.size>2*1024*1024){error.textContent='Choose an image smaller than 2 MB.';input.focus();return}const reader=new FileReader();reader.onload=()=>{state.profile.avatar=reader.result;persist();closeOverlay();render();toast('Profile photo updated')};reader.onerror=()=>{error.textContent='The image could not be read. Try another file.'};reader.readAsDataURL(file)},true);
paths.panel='M4 6h16v12H4zM16 6v12';navMarkup=navMarkupRef;render=renderRef;general=generalRef;
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>state.theme==='system'&&setTheme('system'));addEventListener('popstate',()=>{state.tab=new URLSearchParams(location.search).get('tab')||'general';render()});navMarkup();icons();setTheme(state.theme);
